 function finance(){
  const rows=A.billRows(D.bill),rev=A.sum(rows,'总收入'),settle=A.sum(rows,'结算总金额'),cost=A.sum(rows,'订单成本');
  const dates=rows.map(r=>A.dateKey(r['订单结算时间'])).filter(Boolean).sort();
  const refunds=rows.filter(r=>['买家退包','邮局退包'].includes(r['退款类型']));
  const cats=[...A.group(rows,r=>r['一级类目']||'未提供')].map(([name,rs])=>({name,revenue:A.sum(rs,'总收入'),settle:A.sum(rs,'结算总金额'),cost:A.sum(rs,'订单成本'),count:rs.length})).sort((a,b)=>b.revenue-a.revenue);
  $('content').innerHTML=heading('售后与利润','从结算、成本与退包结构，核对经营质量。',button('售后原始分析 ↗','data-legacy="after"')+button('利润原始分析 ↗','data-legacy="profit"'),'QUALITY / 结算与售后')+
  `<div class="notice">账单日期：${e(dates[0]||'未提供')} 至 ${e(dates.at(-1)||'未提供')} · MYR / RM。售后原始逐单表未保存在 HTML 内，逐单售后重算请通过原模块导入。</div><div class="metrics">${metric('账单总收入',f(rev,2),'RM','原「总收入」字段求和','↗')}${metric('结算总金额',f(settle,2),'RM','原「结算总金额」字段求和','▤')}${metric('订单成本',f(cost,2),'RM','原「订单成本」字段求和','◷')}${metric('原利润率②',pct(A.ratio(settle-cost,rev)),'','（结算总金额 − 订单成本）÷ 总收入','◎')}</div>`+
  `<div class="grid-equal"><section class="panel">${panelHead('收入 → 结算 → 成本','账单原字段对照 · 尚未合并广告、仓储等跨表成本')}<div id="financeBridge" class="chart" role="img" aria-label="收入结算成本对照图"></div><div class="chart-note">结算减成本 ${f(settle-cost,2)} RM 是账单观察值，不宣称完整净利润。</div></section><section class="panel">${panelHead('退包类型记录分布',`${refunds.length} 条买家/邮局退包账单记录；不是唯一订单数`)}<div id="refundChart" class="chart" role="img" aria-label="退包类型账单记录分布"></div></section></div><section class="panel">${panelHead('类目经营对照','按账单一级类目聚合 · 保留原金额符号')}${table(['一级类目','总收入 RM','结算金额 RM','订单成本 RM','结算减成本 RM','账单行数'],cats.map(c=>[e(c.name),f(c.revenue,2),f(c.settle,2),f(c.cost,2),`<span class="${c.settle-c.cost<0?'tone-red':'tone-green'}">${f(c.settle-c.cost,2)}</span>`,f(c.count)]))}</section>`;
  makeChart('financeBridge',{tooltip:{trigger:'axis'},grid:{left:55,right:20,top:15,bottom:25},xAxis:{type:'category',data:['总收入','结算总金额','订单成本','结算减成本'],...axis},yAxis:{type:'value',...axis},series:[{type:'bar',barMaxWidth:40,data:[rev,settle,cost,settle-cost].map((value,i)=>({value,itemStyle:{color:['#537f65','#93b184','#ceb384','#829d92'][i],borderRadius:[4,4,0,0]}}))}]});
  const types=[...A.group(refunds,r=>r['退款类型'])].map(([name,rs])=>({name,value:rs.length}));
  if(types.length)makeChart('refundChart',{tooltip:{trigger:'item'},legend:{bottom:0,itemWidth:8,itemHeight:8},series:[{type:'pie',radius:['45%','72%'],label:{formatter:'{b}\n{c} 行',fontSize:10},data:types}]});else $('refundChart').innerHTML='<div class="empty">当前账单没有这两种退包类型的记录。</div>';
 }
 function legacyTasksPage(){const ts=taskList();$('content').innerHTML=heading('行动中心','把数据依据、优先级和下一步放进同一个工作流。',button('↓ 导出运营清单','data-action="export-tasks"',true),'ACTIONS / 运营执行')+`<div class="notice">${ts.length} 项候选由显式规则选出，广告最多 8 项、库存最多 5 项、达人最多 4 项。它们是优先复核清单，并非全部风险数量。状态仅记录本地工作进度。</div><div class="task-grid">${[['todo','待处理'],['doing','进行中'],['done','已完成']].map(([state,title])=>{const selected=ts.filter(t=>(taskStates[t.id]||'todo')===state);return `<section class="task-column"><h2>${title} ${tag(selected.length+' 项','neutral')}</h2>${selected.length?selected.map(t=>`<article class="task-card">${tag(t.priority,t.priority==='P0'?'danger':'warn')} <span class="muted" style="font-size:9px">${e(nav.find(n=>n[0]===t.module)?.[1])}</span><h3>${e(taskName(t))} · ${e(t.title)}</h3><p>${e(t.reason)}</p><p style="margin-top:8px;color:#5f7852">${e(t.action)}</p><div class="task-meta"><button class="button text small" data-task="${e(t.id)}">查看依据 ↗</button><select data-task-state="${e(t.id)}" aria-label="${e(taskName(t))}的任务状态">${[['todo','待处理'],['doing','进行中'],['done','已完成']].map(([k,v])=>`<option value="${k}" ${state===k?'selected':''}>${v}</option>`).join('')}</select></div></article>`).join(''):'<div class="empty">暂无任务<br>在卡片上切换状态即可移动到这里。</div>'}</section>`;}).join('')}</div>`;}
